/* === sort fix: restore missing sortByTotalForwardCount === */
function updateRanks() {
  const body = document.getElementById("forward-table-body");
  if (!body) return;
  body.querySelectorAll(".draggable-row").forEach((row, index) => {
    const rankCell = row.querySelector("td:first-child");
    if (rankCell) rankCell.textContent = String(index + 1);
  });
}

function sortByTotalForwardCount() {
  const body = document.getElementById("forward-table-body");
  const sortBtn = document.getElementById("sortBtn");
  if (!body || !sortBtn) return;

  const sumRow = body.querySelector(".sum-row");
  if (sumRow) sumRow.remove();

  const rows = Array.from(body.querySelectorAll(".draggable-row"));
  rows.sort((a, b) => {
    const aTotal = parseInt(a.querySelector(".total-forward-count")?.textContent, 10) || 0;
    const bTotal = parseInt(b.querySelector(".total-forward-count")?.textContent, 10) || 0;
    return isDescending ? bTotal - aTotal : aTotal - bTotal;
  });
  rows.forEach((row) => body.appendChild(row));
  if (sumRow) body.appendChild(sumRow);

  updateRanks();
  // 按城市名（第 2 列）同步 companies，避免误用排名列
  companies = rows
    .map((row) => row.querySelector("td:nth-child(2)")?.textContent.trim())
    .filter(Boolean);

  isDescending = !isDescending;
  sortBtn.textContent = `按宣发总量${isDescending ? "降序" : "升序"}排序`;
}
